// Example: 87b24961-b51e-4db8-9226-f198f6518a89
type BrokerageAuthID = openapi_types.UUID

// BrokerageAuthorization A single connection with a brokerage. Note that `Connection` and `Brokerage Authorization` are interchangeable, but the term `Connection` is preferred and used in the doc for consistency.
//
// A connection is usually tied to a single login at a brokerage. A single connection can contain multiple brokerage accounts.
//
// SnapTrade performs de-duping on connections for a given user. If the user has an existing connection with the brokerage, when connecting the brokerage with the same credentials, SnapTrade will return the existing connection instead of creating a new one.
type BrokerageAuthorization struct {
	// Brokerage Describes a brokerage that SnapTrade supports.
	Brokerage *Brokerage `json:"brokerage,omitempty"`

	// CreatedDate Timestamp of when the connection was established in SnapTrade.
	//
	// Example: 2024-08-20T21:56:19.123935Z
	CreatedDate *time.Time `json:"created_date,omitempty"`

	// DataFreshnessMode Indicates the data freshness provided by the institution and by SnapTrade for this connection. The two values are independent; the connection's data is effectively delayed if either value is `delayed`.
	//
	// The "Data freshness" column on the [SnapTrade Institution Support](https://support.snaptrade.com/brokerages) page (Positions & recent orders tab) identifies institutions whose connections are considered delayed on a Real-time plan because either `institution` or `snaptrade` is `delayed`.
	//
	//
	// Example: {"institution":"realtime","snaptrade":"delayed"}
	DataFreshnessMode *struct {
		// Institution Indicates the freshness of the data provided by the institution. `realtime` means the institution provides current data; `delayed` means the institution itself does not allow intra-day data updates.
		Institution BrokerageAuthorizationDataFreshnessModeInstitution `json:"institution"`

		// Snaptrade Indicates how SnapTrade retrieves data for this connection. `realtime` means SnapTrade retrieves current data from the institution during API calls. `delayed` means SnapTrade serves cached data, either because the customer's plan uses Daily data or because retrieving live data from the institution is too latency-intensive.
		//
		// When this value is `delayed`, you can request updated data using the [manual refresh endpoint](/reference/Connections/Connections_refreshBrokerageAuthorization).
		Snaptrade BrokerageAuthorizationDataFreshnessModeSnaptrade `json:"snaptrade"`
	} `json:"data_freshness_mode,omitempty"`

	// Disabled Whether the connection is disabled. A disabled connection can no longer access the latest data from the brokerage, but will continue to return the last cached state. A connection can become disabled for many reasons and differs by brokerage. Here are some common scenarios:
	//
	// - The user has changed their username or password at the brokerage.
	// - The user has explicitly removed the access grant at the brokerage.
	// - The session has expired at the brokerage and now requires explicit user re-authentication.
	//
	// Please see [this guide](/docs/fix-broken-connections) on how to fix a disabled connection.
	//
	//
	// Example: false
	Disabled *bool `json:"disabled,omitempty"`

	// DisabledDate Timestamp of when the connection was disabled in SnapTrade.
	//
	// Example: 2022-01-21T15:11:19.217-05:00
	DisabledDate *time.Time `json:"disabled_date,omitempty"`

	// Id Unique identifier for the connection (brokerage_authorization_id). This is the UUID used to reference the connection in SnapTrade.
	//
	// Example: 87b24961-b51e-4db8-9226-f198f6518a89
	Id *BrokerageAuthID `json:"id,omitempty"`

	// IsEligibleForPayout Whether the connection is eligible for a payout. This is an experimental field that is NOT generally available for all partners. Do not use in production without speaking to the SnapTrade team.
	//
	// Example: true
	IsEligibleForPayout *bool `json:"is_eligible_for_payout,omitempty"`

	// Meta Additional data about the connection. This information is specific to the brokerage and there's no standard format for this data. This field is deprecated and subject to removal in a future version.
	//
	// Example: {"identifier":123456}
	// Deprecated: this property has been marked as deprecated upstream, but no `x-deprecated-reason` was set
	Meta *map[string]interface{} `json:"meta,omitempty"`

	// Name A short, human-readable name for the connection.
	//
	// Example: Connection-1
	Name *string `json:"name,omitempty"`

	// Type Whether the connection is read-only or trade-enabled. A read-only connection can only be used to fetch data, while a trade-enabled connection can be used to place trades. Valid values are `read` and `trade`.
	//
	// Example: trade
	Type *string `json:"type,omitempty"`

	// UpdatedDate Timestamp of when the connection was last updated in SnapTrade. This field is deprecated. Please let us know if you have a valid use case for this field.
	//
	// Example: 2024-08-20T21:56:20.057224Z
	// Deprecated: this property has been marked as deprecated upstream, but no `x-deprecated-reason` was set
	UpdatedDate *time.Time `json:"updated_date,omitempty"`
}

// BrokerageAuthorizationDataFreshnessModeInstitution Indicates the freshness of the data provided by the institution. `realtime` means the institution provides current data; `delayed` means the institution itself does not allow intra-day data updates.
type BrokerageAuthorizationDataFreshnessModeInstitution string

