// HoldingsStatus Status of account holdings sync. SnapTrade syncs holdings from the brokerage under the following conditions:
// 1. Initial connection - SnapTrade syncs all holdings (positions, balances, recent orders, and transactions) immediately after the connection is established.
// 2. Daily sync - Once a day SnapTrade refreshes all holdings from the brokerage.
// 3. Manual sync - You can trigger a refresh of holdings with the [manual refresh](/reference/Connections/Connections_refreshBrokerageAuthorization) endpoint.
type HoldingsStatus struct {
	// HoldingsUnavailable Indicates that the brokerage does not expose this account's holdings to SnapTrade, so the
	// empty positions and balances reported for it do not mean the account is empty. This is set
	// for accounts served by a separate brokerage system that we cannot read, such as Vanguard
	// employer-sponsored retirement plans. When this is `true`, prefer the account's total value
	// over the sum of its positions and cash, and note that `initial_sync_completed` and
	// `last_successful_sync` may still reflect an earlier sync.
	//
	//
	// Example: true
	HoldingsUnavailable *bool `json:"holdings_unavailable,omitempty"`

	// InitialSyncCompleted Indicates if the initial sync of holdings has been completed. For accounts with a large number of positions/orders/transactions, the initial sync may take a while to complete.
	//
	// Example: true
	InitialSyncCompleted *bool `json:"initial_sync_completed,omitempty"`

	// LastSuccessfulSync The last time holdings were successfully synced by SnapTrade.
	LastSuccessfulSync *HoldingsSyncStatusDate `json:"last_successful_sync,omitempty"`
}

// HoldingsSyncStatusDate Date in ISO 8601 format or null (YYYY-MM-DD HH:MM:SS.mmmmmmTZ)
//
// Example: 2024-06-28 18:42:46.561408+00:00
type HoldingsSyncStatusDate = time.Time

